sysmlv2:
// SysML v2 metin gösterimi (alt küme) — Örnek Model
// SysML Modelleyici SÜRÜM ile üretildi: TARİH
// Not: davranış gövdeleri ve bazı ilişkiler yorum olarak aktarılır; Pilot uygulama / Cameo 2024x ile içe almadan önce gözden geçirin.

package 'Örnek Model' {
    private import ScalarValues::*;
    package 'Arayüzler ve Tipler' {
        port def 'GüçArayüzü' {
            out item 'güç' : 'Arayüzler ve Tipler'::Gerilim;
        }
        port def 'VeriArayüzü' {
            out item veri : 'Arayüzler ve Tipler'::'SensörVerisi';
        }
        attribute def Gerilim :> ScalarValues::Real {
            // birim: V
        }
        attribute def 'Kütle' :> ScalarValues::Real {
            // birim: kg
        }
        enum def 'ÇalışmaModu' {
            enum 'Kapalı';
            enum Test;
            enum 'Hazır';
            enum 'Arıza';
        }
        item def 'SensörVerisi' {
            attribute 'ölçüm' : ScalarValues::Real;
            attribute 'zamanDamgası' : ScalarValues::Real; // [s]
        }
    }
    package 'Davranış' {
        action def 'Kendi Kendine Test' {
            fork fork1;
            action 'Güç hattı kontrolü';
            action 'Sensör kontrolü';
            join join1;
            action 'Test sonucunu kaydet';
            succession first start then fork1;
            succession first fork1 then 'Güç hattı kontrolü';
            succession first fork1 then 'Sensör kontrolü';
            succession first 'Güç hattı kontrolü' then join1;
            succession first 'Sensör kontrolü' then join1;
            succession first join1 then 'Test sonucunu kaydet';
            succession first 'Test sonucunu kaydet' then done;
            flow first 'Test sonucunu kaydet' then 'sonuç';
        }
        action def 'Sistemi Başlat' {
            action 'Güç ver';
            action 'Kendi kendine test yap' : 'Davranış'::'Kendi Kendine Test';
            decide decision1;
            action 'Hazır durumunu bildir';
            action 'Hata raporla';
            succession first start then 'Güç ver';
            succession first 'Güç ver' then 'Kendi kendine test yap';
            succession first 'Kendi kendine test yap' then decision1;
            succession first 'Hazır durumunu bildir' then done;
            succession first 'Hata raporla' then done;
            succession first decision1 then 'Hazır durumunu bildir'; // [başarılı]
            succession first decision1 then 'Hata raporla'; // [hata]
        }
    }
    package 'Doğrulama' {
        verification def 'Açılış süresi testi' {
            objective {
                verify Gereksinimler::'Sistem Gereksinimleri'::'SYS-002';
            }
            // sonuç: Geçti
        }
        verification def 'Besleme gerilimi testi' {
            objective {
                verify Gereksinimler::'Sistem Gereksinimleri'::'SYS-001';
            }
            // sonuç: Kaldı
        }
        verification def 'Besleme gerilimi testi (tekrar)' {
            objective {
                verify Gereksinimler::'Sistem Gereksinimleri'::'SYS-001';
            }
            // sonuç: Planlandı
        }
        verification def 'Çevresel gerilim taraması (ESS)' {
            objective {
                verify Gereksinimler::'Sistem Gereksinimleri'::'SYS-005';
            }
            // sonuç: Planlandı
        }
        verification def 'Durum bildirimi analizi' {
            objective {
                verify Gereksinimler::'Sistem Gereksinimleri'::'SYS-003';
                verify Gereksinimler::'Alt Sistem Gereksinimleri'::'Kontrol Birimi'::'SUB-004';
            }
            // sonuç: Koşullu
        }
        verification def 'EMC kalifikasyon testi' {
            // sonuç: Planlandı
        }
        verification def 'Güç birimi birim testi' {
            objective {
                verify Gereksinimler::'Alt Sistem Gereksinimleri'::'Güç Birimi'::'SUB-001';
            }
            // sonuç: Geçti
        }
        verification def 'Kontrol yazılımı açılış testi' {
            objective {
                verify Gereksinimler::'Alt Sistem Gereksinimleri'::'Kontrol Birimi'::'SUB-002';
            }
            // sonuç: Planlandı
        }
        verification def 'Rastgele titreşim kalifikasyon testi' {
            objective {
                verify Gereksinimler::'Sistem Gereksinimleri'::'SYS-005';
            }
            // sonuç: Planlandı
        }
        verification def 'Sensör veri hızı ölçümü' {
            objective {
                verify Gereksinimler::'Alt Sistem Gereksinimleri'::'Sensör Birimi'::'SUB-003';
            }
            // sonuç: Planlandı
        }
    }
    package Gereksinimler {
        package 'Alt Sistem Gereksinimleri' {
            package 'Güç Birimi' {
                requirement def <'SUB-001'> 'Güç dönüşümü' {
                    doc /* Güç birimi 28 V girişten 5 V ve 12 V regüle çıkış üretecektir. */
                    // doğrulama yöntemi: Test, Analiz
                }
            }
            package 'Kontrol Birimi' {
                requirement def <'SUB-005'> 'Bakım arayüzü' {
                    doc /* Kontrol birimi bakım için seri arayüz sağlayacaktır. */
                    // doğrulama yöntemi: Muayene
                }
                requirement def <'SUB-004'> 'Durum mesajı' {
                    doc /* Kontrol birimi durum mesajını 1 Hz ile yayınlayacaktır. */
                }
                requirement def <'SUB-002'> 'Kendi kendine test' {
                    doc /* Kontrol birimi açılışta kendi kendine testi 20 s içinde tamamlayacaktır. */
                    // doğrulama yöntemi: Test
                }
            }
            package 'Sensör Birimi' {
                requirement def <'SUB-003'> 'Sensör veri hızı' {
                    doc /* Sensör birimi veriyi en az 100 Hz ile kontrol birimine iletecektir. */
                    // doğrulama yöntemi: Test
                }
            }
        }
        package 'Sistem Gereksinimleri' {
            requirement def <'SYS-001'> 'Çalışma gerilimi' {
                doc /* Sistem 28 V DC ± %10 besleme ile çalışacaktır. */
                // doğrulama yöntemi: Test
            }
            requirement def <'SYS-005'> 'Çevresel dayanım' {
                doc /* Sistem MIL-STD-810H yöntem 514.8 titreşim koşullarında çalışmasını sürdürecektir. */
            }
            requirement def <'SYS-003'> 'Durum bildirimi' {
                doc /* Sistem operatöre çalışma durumunu uygun şekilde ve hızlı bildirecektir. */
                // doğrulama yöntemi: Gösterim
            }
            requirement def <'SYS-002'> 'Hazır olma süresi' {
                doc /* Sistem enerji verildikten sonra en geç 30 s içinde hazır durumuna geçecektir. */
                // doğrulama yöntemi: Test
            }
            requirement def <'SYS-004'> 'Kütle' {
                doc /* Sistemin toplam kütlesi 45 kg'ı aşmayacaktır. */
                // doğrulama yöntemi: Muayene
            }
        }
    }
    package 'Görünümler' {
        viewpoint def 'Müşteri Bakış Açısı' {
            // paydaşlar: Müşteri, proje yöneticisi
            // kaygılar: Sistem gereksinimleri karşılanıyor mu? Doğrulama durumu nedir?
        }
        view def 'Müşteri İnceleme Görünümü' {
            doc /* Kritik tasarım gözden geçirmesi (CDR) için hazırlanan görünüm. */
            expose Gereksinimler::**;
        }
    }
    package 'Güç Kaynağı Alternatifleri' {
        part def 'Li-ion Paket' {
            attribute 'çevrimÖmrü' : ScalarValues::Real = 1500; // [çevrim]
            attribute kapasite : ScalarValues::Real = 900; // [Wh]
            attribute 'kütle' : ScalarValues::Real = 3.1; // [kg]
            attribute maliyet : ScalarValues::Real = 42; // [k€]
        }
        part def 'LiFePO4 Paket' {
            attribute 'çevrimÖmrü' : ScalarValues::Real = 4000; // [çevrim]
            attribute kapasite : ScalarValues::Real = 820; // [Wh]
            attribute 'kütle' : ScalarValues::Real = 4.4; // [kg]
            attribute maliyet : ScalarValues::Real = 35; // [k€]
        }
        part def 'NiMH Paket' {
            attribute 'çevrimÖmrü' : ScalarValues::Real = 900; // [çevrim]
            attribute kapasite : ScalarValues::Real = 600; // [Wh]
            attribute 'kütle' : ScalarValues::Real = 5.6; // [kg]
            attribute maliyet : ScalarValues::Real = 22; // [k€]
        }
    }
    package 'Kullanım Senaryoları' {
        part def 'Operatör'; // aktör
        use case def 'Durum İzle';
        use case def 'Görev Planla';
        use case def 'Kendi Kendine Test';
        use case def 'Sistemi Başlat' {
            /* Operatör: Sistemi başlatır
Sistem: Kendi kendine test yapar
Sistem → Operatör: Hazır durumunu bildirir */
        }
    }
    package 'Örnekler';
    package Profil;
    package 'Risk Kaydı';
    package 'Test Kaynakları';
    package 'Test Numuneleri';
    package 'Test Profilleri';
    package Uygunsuzluklar;
    package 'Yapı' {
        part def 'Araç Sistemi' {
            doc /* Sistem bağlam bloğu */
            state def 'Araç Sistemi Durumları' {
                state 'Kapalı';
                state 'Kendi Kendine Test' { entry action { /* açılışSayısı += 1 */ } do action { /* BIT çalıştır; bitSonuc = sıcaklık < 70 */ } }
                state 'Hazır' { entry action { /* durum bildir */ } }
                state 'Arıza' { entry action { /* hata kaydet */ } }
                state 'Görevde' { entry action { /* görev kaydı aç */ } do action { /* der(sıcaklık) = 0.5 - (sıcaklık - 25) / 60 */ } }
                state Arama;
                state Takip;
                state choice1; // seçim (choice)
                entry; then 'Kapalı';
                transition first 'Kapalı' accept 'güçVer' then 'Kendi Kendine Test';
                transition first 'Kendi Kendine Test' then choice1;
                transition first choice1 if bitSonuc == 1 then 'Hazır';
                transition first choice1 then 'Arıza'; // else
                transition first 'Arıza' accept 'sıfırla' then 'Kapalı';
                entry; then Arama;
                transition first Arama accept hedefBulundu then Takip;
                transition first Takip accept 'hedefKayıp' then Arama;
                transition first 'Hazır' accept 'görevBaşlat' then 'Görevde';
                transition first 'Görevde' accept 'görevBitti' then 'Hazır';
                transition first 'Hazır' accept after 30 [s] do action { /* sıcaklık = sıcaklık + 5 */ } then 'Kapalı';
            }
            part 'güçBirimi' : 'Yapı'::'Güç Birimi';
            part kontrolBirimi : 'Yapı'::'Kontrol Birimi';
            part 'sensörBirimi' : 'Yapı'::'Sensör Birimi'[2]; // varyant: UzunMenzil || !Hafif
            attribute 'açılışSayısı' : ScalarValues::Integer = 0;
            attribute bitSonuc : ScalarValues::Integer = 0;
            attribute 'kütle' : 'Arayüzler ve Tipler'::'Kütle'; // [kg]
            attribute 'sıcaklık' : ScalarValues::Real = 25; // [°C]
            connect 'güçBirimi'.'güçÇıkış' to kontrolBirimi.'güçGiriş';
            interface 'sensörBirimi'.'veriÇıkış' to kontrolBirimi.'veriGiriş';
            satisfy Gereksinimler::'Sistem Gereksinimleri'::'SYS-004' by self;
        }
        part def 'Güç Birimi' {
            constraint 'güçHesabı' : 'Yapı'::'Güç Denklemi';
            attribute 'akım' : ScalarValues::Real = 3.5; // [A]
            attribute gerilim : 'Arayüzler ve Tipler'::Gerilim = 28; // [V]
            attribute 'güç' : ScalarValues::Real; // [W]
            attribute 'kütle' : 'Arayüzler ve Tipler'::'Kütle' = 4.2; // [kg]
            port 'güçÇıkış' : 'Arayüzler ve Tipler'::'GüçArayüzü';
            satisfy Gereksinimler::'Alt Sistem Gereksinimleri'::'Güç Birimi'::'SUB-001' by self;
        }
        part def 'Kontrol Birimi' {
            attribute 'kütle' : 'Arayüzler ve Tipler'::'Kütle' = 2.8; // [kg]
            attribute mod : 'Arayüzler ve Tipler'::'ÇalışmaModu' = 'Arayüzler ve Tipler'::'ÇalışmaModu'::'Kapalı';
            port 'güçGiriş' : ~'Arayüzler ve Tipler'::'GüçArayüzü';
            port 'veriGiriş' : ~'Arayüzler ve Tipler'::'VeriArayüzü';
            satisfy Gereksinimler::'Alt Sistem Gereksinimleri'::'Kontrol Birimi'::'SUB-002' by self;
        }
        part def 'Sensör Birimi' {
            attribute 'kütle' : 'Arayüzler ve Tipler'::'Kütle' = 1.6; // [kg]
            port 'veriÇıkış' : 'Arayüzler ve Tipler'::'VeriArayüzü';
            satisfy Gereksinimler::'Alt Sistem Gereksinimleri'::'Sensör Birimi'::'SUB-003' by self;
        }
        part def 'Soğutma Döngüsü' {
            doc /* Denklem takımı örneği */
            constraint nokta : 'Yapı'::'Çalışma Noktası';
            attribute H : ScalarValues::Real; // [m]
            attribute H0 : ScalarValues::Real = 40; // [m]
            attribute k1 : ScalarValues::Real = 0.02;
            attribute k2 : ScalarValues::Real = 0.05;
            attribute Q : ScalarValues::Real; // [L/min]
        }
        constraint def 'Çalışma Noktası' {
            doc /* Pompa eğrisi ile hat direnci eğrisinin kesişimi; H ve Q birlikte (denklem takımı) çözülür. */
            in H : ScalarValues::Real;
            in H0 : ScalarValues::Real;
            in k1 : ScalarValues::Real;
            in k2 : ScalarValues::Real;
            in Q : ScalarValues::Real;
            (H == H0 - k1 * Q^2) and
            (H == k2 * Q^2)
        }
        constraint def 'Güç Denklemi' {
            in P : ScalarValues::Real;
            in V : ScalarValues::Real;
            in I : ScalarValues::Real;
            (P == V * I) and
            (P <= 120)
        }
    }

    // ---- ilişkiler ----
    #derivation dependency from Gereksinimler::'Sistem Gereksinimleri'::'SYS-001' to Gereksinimler::'Alt Sistem Gereksinimleri'::'Güç Birimi'::'SUB-001';
    #derivation dependency from Gereksinimler::'Sistem Gereksinimleri'::'SYS-002' to Gereksinimler::'Alt Sistem Gereksinimleri'::'Kontrol Birimi'::'SUB-002';
    #derivation dependency from Gereksinimler::'Sistem Gereksinimleri'::'SYS-002' to Gereksinimler::'Alt Sistem Gereksinimleri'::'Sensör Birimi'::'SUB-003';
    #derivation dependency from Gereksinimler::'Sistem Gereksinimleri'::'SYS-003' to Gereksinimler::'Alt Sistem Gereksinimleri'::'Kontrol Birimi'::'SUB-004';
    #refinement dependency from 'Test Profilleri'::'Kalifikasyon rastgele titreşim' to Gereksinimler::'Sistem Gereksinimleri'::'SYS-005';
    satisfy Gereksinimler::'Sistem Gereksinimleri'::'SYS-002' by 'Davranış'::'Sistemi Başlat';
    satisfy Gereksinimler::'Alt Sistem Gereksinimleri'::'Kontrol Birimi'::'SUB-002' by 'Davranış'::'Sistemi Başlat'::'Kendi kendine test yap';
    satisfy Gereksinimler::'Alt Sistem Gereksinimleri'::'Kontrol Birimi'::'SUB-004' by 'Davranış'::'Sistemi Başlat'::'Hazır durumunu bildir';
    allocate 'Davranış'::'Sistemi Başlat'::'Güç ver' to 'Yapı'::'Güç Birimi';
    allocate 'Davranış'::'Sistemi Başlat'::'Kendi kendine test yap' to 'Yapı'::'Kontrol Birimi';
    allocate 'Davranış'::'Sistemi Başlat'::'Hazır durumunu bildir' to 'Yapı'::'Kontrol Birimi';
    allocate 'Davranış'::'Sistemi Başlat' to 'Yapı'::'Araç Sistemi';
    dependency from 'Davranış' to 'Yapı';

    // ---- varyantlar ----
    // konfigürasyon Temel: Hafif
    // konfigürasyon Uzun Menzil: UzunMenzil
}
